    [SerializeField] private float _toppleAngle = 82f;
    [Tooltip("World units the sprite sinks as it falls.")]
    [SerializeField] private float _sink = 0.35f;

    private ResourceNode _node;

    private void Awake()
    {
        _node = GetComponent<ResourceNode>();
        if (_visualRoot == null) _visualRoot = transform;
        if (_spriteRenderer == null) _spriteRenderer = GetComponentInChildren<SpriteRenderer>();
    }

    private void OnEnable()  { _node.OnDepleted += HandleDepleted; }
    private void OnDisable() { if (_node != null) _node.OnDepleted -= HandleDepleted; }

    private void HandleDepleted()
    {
        _node.OnDepleted -= HandleDepleted;

        foreach (Collider col in GetComponentsInChildren<Collider>())
            col.enabled = false;

        // Stop the billboard from overwriting the topple rotation each LateUpdate.
        Billboard billboard = GetComponentInChildren<Billboard>();
        if (billboard != null) billboard.enabled = false;

        StartCoroutine(FallRoutine());
    }

    private IEnumerator FallRoutine()
    {
        Vector3 startPos = _visualRoot.position;
        Quaternion startRot = _visualRoot.rotation;
        Vector3 axis = Random.value < 0.5f ? Vector3.forward : Vector3.back;

        Color baseColor = _spriteRenderer != null ? _spriteRenderer.color : Color.white;
        float total = Mathf.Max(_fallDuration, _fadeDuration);
        float t = 0f;

        while (t < total)
        {
            t += Time.deltaTime;
            float fall = Mathf.Clamp01(t / _fallDuration);
            float eased = fall * fall; // accelerate as it falls
            _visualRoot.rotation = startRot * Quaternion.AngleAxis(_toppleAngle * eased, axis);
            _visualRoot.position = startPos + Vector3.down * (_sink * eased);

            if (_spriteRenderer != null)
            {
                float alpha = baseColor.a * (1f - Mathf.Clamp01(t / _fadeDuration));
                _spriteRenderer.color = new Color(baseColor.r, baseColor.g, baseColor.b, alpha);
            }
            yield return null;
        }

        Destroy(gameObject);
    }
}

using System.Collections;
using UnityEngine;

/// <summary>
/// Positional recoil on a <see cref="ResourceNode"/> when it's hit — a quick decaying nudge so the
/// node visibly rocks from the blow. Amplitude scales with the damage dealt (heavy swings rock it
/// harder). Nudges the node root's position only: the sprite's rotation is owned by
/// <see cref="Billboard"/>, so a positional shake reads cleanly without fighting it.
/// </summary>
[RequireComponent(typeof(ResourceNode))]
public class ResourceShake : MonoBehaviour
{
    [Tooltip("Transform to nudge. Defaults to this node's transform.")]
    [SerializeField] private Transform _shakeRoot;
    [SerializeField] private float _duration = 0.18f;
    [SerializeField] private float _amplitude = 0.09f;
    [Tooltip("Damage that produces a full-strength shake; less damage shakes proportionally less.")]
    [SerializeField] private float _damageForFullShake = 3f;

    private ResourceNode _node;
    private Coroutine _routine;
    private Vector3 _basePos;
    private int _lastHealth;

    private void Awake()
    {
        _node = GetComponent<ResourceNode>();
        if (_shakeRoot == null) _shakeRoot = transform;
        _basePos = _shakeRoot.localPosition;
    }

    private void Start() => _lastHealth = _node.CurrentHealth;

    private void OnEnable()  { _node.OnDamaged += HandleDamaged; }
    private void OnDisable()
    {
        if (_node != null) _node.OnDamaged -= HandleDamaged;
        if (_shakeRoot != null) _shakeRoot.localPosition = _basePos;
    }

    private void HandleDamaged(int remaining)
    {
        int dmg = Mathf.Max(1, _lastHealth - remaining);
        _lastHealth = remaining;
        float strength = 0.4f + 0.6f * Mathf.Clamp01(dmg / Mathf.Max(1f, _damageForFullShake));

        if (_routine != null) StopCoroutine(_routine);
        _routine = StartCoroutine(ShakeRoutine(strength));
    }

    private IEnumerator ShakeRoutine(float strength)
    {
        Vector2 r = Random.insideUnitCircle.normalized;
        Vector3 dir = new Vector3(r.x, 0f, r.y);
        float t = 0f;
        while (t < _duration)
        {
            t += Time.deltaTime;
            float decay = 1f - (t / _duration);
            float wobble = Mathf.Sin(t * 55f) * decay * strength;
            _shakeRoot.localPosition = _basePos + dir * (_amplitude * wobble);
            yield return null;
        }
        _shakeRoot.localPosition = _basePos;
        _routine = null;
    }
}

using UnityEngine;
using System.Collections.Generic;

/// <summary>
/// Maps (ToolType, ResourceType) → damage multiplier. Controls which tools are
/// effective against which resources. Unmatched combinations deal 0 damage
/// (wrong tool). Designers can tune this via the Inspector without code changes.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Resource/Tool Effectiveness Table", fileName = "ToolEffectivenessTable")]
public class ToolEffectivenessTable : ScriptableObject
{
    [System.Serializable]
    public struct Entry
    {
        public ToolType toolType;
        public ResourceType resourceType;
        [Range(0f, 3f)] public float multiplier;
    }

    [SerializeField] private Entry[] _entries = System.Array.Empty<Entry>();

    /// <summary>
    /// Default multiplier when no entry matches. 0 = wrong tool (no damage).
    /// The wrench as a multitool gets a small non-zero default so it can
    /// harvest anything, just inefficiently.
    /// </summary>
    [SerializeField] private float _defaultMultiplier = 0.3f;

    private Dictionary<(ToolType, ResourceType), float> _lookup;

    private void BuildLookup()
    {
        _lookup = new Dictionary<(ToolType, ResourceType), float>(_entries.Length);
        foreach (var e in _entries)
            _lookup[(e.toolType, e.resourceType)] = e.multiplier;
    }

    /// <summary>
    /// Get the damage multiplier for a tool/resource combination.
    /// Returns the matched entry, or _defaultMultiplier for the wrench,
    /// or 0 for other unmatched tools.
    /// </summary>
    public float GetMultiplier(ToolType tool, ResourceType resource)
    {
        if (_lookup == null) BuildLookup();

        if (_lookup.TryGetValue((tool, resource), out float m))
            return m;

        // Wrench as multitool: partial effectiveness against everything
        if (tool == ToolType.Wrench)
            return _defaultMultiplier;

        return 0f;
    }
}

