    [SerializeField] private float _cooldownTime = 0.1f;

    [Tooltip("Hold longer than this (seconds) to enter windup. Taps skip straight to swing.")]
    [SerializeField] private float _quickSwingThreshold = 0.12f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _movement;
    private PowerBuildupManager _buildup;
    private float _cooldown;
    private float _windupStartTime;

    public bool IsCharging => _buildup != null && _buildup.IsCharging && _buildup.CurrentType == ActionType.Swing;
    public float ChargeNormalized => _buildup != null ? _buildup.ChargeNormalized : 0f;

    /// <summary>True while the swing animation is still playing (movement blocked).</summary>
    public bool IsSwinging { get; private set; }

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
        _movement   = GetComponent<SolarpunkCharacterController>();
    }

    private void Update()
    {
        // Block movement while swinging
        if (IsSwinging)
        {
            if (_movement != null) _movement.CanMove = false;

            // Check if the swing animation has finished
            var driver = _animDriver as FlynnAnimationDriver;
            if (driver != null && !driver.IsAttacking)
                IsSwinging = false;
        }

        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable)
        {
            if (IsCharging) _buildup.CancelCharge();
            if (_animDriver is FlynnAnimationDriver drv)
                drv.CancelSwingWindup();
            return;
        }

        if (_buildup == null) _buildup = PowerBuildupManager.Instance;

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
        {
            if (_buildup != null) _buildup.BeginCharge(ActionType.Swing);
            _windupStartTime = Time.time;
            // Face the mouse aim point and start the windup animation
            if (_animDriver != null)
            {
                _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);
                _animDriver.BeginSwingWindup();
            }
        }
        else if (IsCharging && Input.GetMouseButtonUp(0))
        {
            bool quickSwing = Time.time - _windupStartTime < _quickSwingThreshold;
            DoSwing(quickSwing);
        }
    }

    private void DoSwing(bool quickSwing = false)
    {
        if (_buildup == null) return;

        ChargeResult result = _buildup.ReleaseCharge();

        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);

        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float speed = result.AnimSpeed > 0f ? result.AnimSpeed : 1f;
        if (_animDriver != null)
        {
            if (quickSwing)
            {
                _animDriver.CancelSwingWindup();
                _animDriver.TriggerSwing();
            }
            else
            {
                _animDriver.ReleaseSwing(animIndex, speed);
            }
        }

        IsSwinging = true;
        if (_movement != null) _movement.CanMove = false;

        if (_swingArc != null)
            _swingArc.Play(_aimer.WorldAimPoint);

        _cooldown = _cooldownTime;

        int damage = result.Damage > 0 ? result.Damage : 1;
        GameObject target = _aimer.HoveredGameObject;
        if (_playerInit != null && damage > 0)
            _playerInit.EmitHit(_aimer.WorldAimPoint, target, damage);

        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;
        PublishEvent(new ToolSwingStarted(tool, _aimer.WorldAimPoint));
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;

/// <summary>
/// Placeholder wrench swing VFX: a slash line that draws from the player toward
/// the hit point, plus an expanding ring at the endpoint. Both fade out.
/// Will be swapped for real sprite anims later.
/// </summary>
[RequireComponent(typeof(LineRenderer))]
public class WrenchSwingArc : MonoBehaviour
{
    [Header("Slash Line")]
    [SerializeField] private float _slashDrawTime = 0.1f;
    [SerializeField] private float _slashFadeTime = 0.15f;
    [SerializeField] private float _slashWidth = 0.1f;

    [Header("Impact Ring")]
    [SerializeField] private float _ringMaxRadius = 0.5f;
    [SerializeField] private float _ringExpandTime = 0.1f;
    [SerializeField] private float _ringFadeTime = 0.2f;
    [SerializeField] private int _ringSegments = 24;

    [Header("Common")]
    [SerializeField] private float _arcHeight = 0.8f;
    [SerializeField] private Color _slashColor = new Color(1f, 0.9f, 0.6f);
    [SerializeField] private Color _ringColor = new Color(1f, 0.7f, 0.3f);

    private LineRenderer _slashLr;
    private LineRenderer _ringLr;
    private bool _playing;
    private float _timer;
    private Vector3 _startPos;
    private Vector3 _hitPos;

    private void Awake()
    {
        // Slash LineRenderer is configured in the inspector — only set runtime properties
        _slashLr = GetComponent<LineRenderer>();
        _slashLr.useWorldSpace = true;
        _slashLr.positionCount = 0;
        _slashLr.enabled = false;

        // Ring is created at runtime — needs full setup
        var ringGo = new GameObject("Ring");
        ringGo.transform.SetParent(transform, false);
        _ringLr = ringGo.AddComponent<LineRenderer>();
        _ringLr.useWorldSpace = true;
        _ringLr.startWidth = _slashWidth * 0.6f;
        _ringLr.endWidth = _slashWidth * 0.2f;
        _ringLr.positionCount = 0;
        _ringLr.enabled = false;
        _ringLr.numCornerVertices = 4;
        _ringLr.numCapVertices = 4;
        _ringLr.loop = false;
        _ringLr.material = new Material(Shader.Find("Sprites/Default"));

        HideAll();
    }

    public void Play(Vector3 worldAimPoint)
    {
        _startPos = transform.position + Vector3.up * _arcHeight;
        _hitPos = worldAimPoint;

        _timer = 0f;
        _playing = true;
    }

    private void Update()
    {
        if (!_playing) return;

        _timer += Time.deltaTime;

        float slashTotal = _slashDrawTime + _slashFadeTime;
        float ringTotal = _ringExpandTime + _ringFadeTime;
        float total = Mathf.Max(slashTotal, ringTotal);

        if (_timer >= total)
        {
            _playing = false;
            HideAll();
            return;
        }

        UpdateSlash();
        UpdateRing();
    }

    private void UpdateSlash()
    {
        float drawT = Mathf.Clamp01(_timer / _slashDrawTime);

        float alpha = _timer <= _slashDrawTime
            ? 1f
            : Mathf.Clamp01(1f - (_timer - _slashDrawTime) / _slashFadeTime);

        if (alpha <= 0f) { _slashLr.enabled = false; return; }

        Vector3 tip = Vector3.Lerp(_startPos, _hitPos, drawT);
        _slashLr.enabled = true;
        _slashLr.positionCount = 2;
        _slashLr.SetPosition(0, _startPos);
        _slashLr.SetPosition(1, tip);

        Color c = _slashColor;
        _slashLr.startColor = new Color(c.r, c.g, c.b, alpha);
        _slashLr.endColor = new Color(c.r, c.g, c.b, alpha * 0.3f);
    }

    private void UpdateRing()
    {
        float ringStart = _slashDrawTime * 0.5f;
        float localT = _timer - ringStart;
        if (localT < 0f) { _ringLr.enabled = false; return; }

        float expandT = Mathf.Clamp01(localT / _ringExpandTime);

        float alpha = localT <= _ringExpandTime
            ? 1f
            : Mathf.Clamp01(1f - (localT - _ringExpandTime) / _ringFadeTime);

        if (alpha <= 0f) { _ringLr.enabled = false; return; }

        float radius = Mathf.Lerp(0.05f, _ringMaxRadius, expandT);

        _ringLr.enabled = true;
        _ringLr.positionCount = _ringSegments + 1;
        for (int i = 0; i <= _ringSegments; i++)
        {
            float angle = (i / (float)_ringSegments) * Mathf.PI * 2f;
            Vector3 offset = new Vector3(Mathf.Cos(angle) * radius, 0f, Mathf.Sin(angle) * radius);
            _ringLr.SetPosition(i, _hitPos + offset);
        }

        Color c = _ringColor;
        _ringLr.startColor = new Color(c.r, c.g, c.b, alpha);
        _ringLr.endColor = new Color(c.r, c.g, c.b, alpha * 0.5f);
    }

    private void HideAll()
    {
        _slashLr.enabled = false;
        _ringLr.enabled = false;
    }
}

using UnityEngine;

/// <summary>
/// Single-responsibility component that owns all mouse → world target detection. Every interaction
/// reads what's under the cursor from here; nothing keeps its own proximity registry.
///
/// It no longer casts its own rays: <see cref="MousePointer"/> does ONE cursor raycast per frame
/// (against its combined world mask) and this component derives every hovered target from that one
/// shared hit. The object under the cursor is resolved once; each concern asks it for the component
/// it cares about and applies its own range gate. Consequence of the single union cast: the closest
/// object under the cursor wins across all layers (uniform occlusion) — there are no per-concern
/// masks that can see a target through something in front of it.
///
/// Other systems read the public properties; this component only ever reads — it writes nothing.
/// Requires a <see cref="MousePointer"/> in the scene whose mask covers ground + resources + pickups
/// + grapple + melee surfaces (the union of what used to be per-concern masks here).
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class PlayerMouseAimer : MonoBehaviour
{
    [SerializeField] private float _maxAimDistance = 30f;

    /// <summary>Max distance from the player to a resource or pickup for it to count as interactable.</summary>
    [SerializeField] private float _interactionRange = 3f;

    /// <summary>Public access to the interaction range for other controllers.</summary>
    public float InteractionRange => _interactionRange;

    [Tooltip("Max distance from the player to a melee surface for a wrench swing to register its tool/hit.")]
    [SerializeField] private float _meleeRange = 2.5f;

    private MousePointer _pointer;

    // ── Public properties ─────────────────────────────────────────────────────

    /// <summary>World-space position the mouse cursor is pointing at.</summary>
    public Vector3 WorldAimPoint { get; private set; }

    /// <summary>
    /// The ResourceNode the mouse ray is pointing at, or null.
    /// Only set when the hit node is within <see cref="_interactionRange"/> of the player.
    /// </summary>
    public ResourceNode HoveredResource { get; private set; }

    /// <summary>
    /// The WorldItemPickup the mouse ray is pointing at, or null. (Legacy; new world objects use
    /// <see cref="WorldItem"/> / <see cref="HoveredKeyPickup"/>.) Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItemPickup HoveredPickup { get; private set; }

    /// <summary>
    /// The non-auto-collect <see cref="WorldItem"/> under the cursor (e.g. the wrench), or null.
    /// These require the pickup key — auto-collecting items magnet themselves and never appear here.
    /// Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItem HoveredKeyPickup { get; private set; }

    /// <summary>The RopeAnchor the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopeAnchor HoveredAnchor { get; private set; }

    /// <summary>The RopePullable the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopePullable HoveredPullable { get; private set; }

    /// <summary>Exact world surface point hit on the current grapple target. Valid only when an anchor or pullable is hovered.</summary>
    public Vector3 HoveredGrapplePoint { get; private set; }

    /// <summary>
    /// Animator AttackIndex of the surface under the cursor within <see cref="_meleeRange"/>.
    /// Defaults to 4 (wrench / "air") when nothing meleeable is in reach. The wrench swing
    /// reads this to decide which tool to transform into.
    /// </summary>
    public int SwingAnimIndex { get; private set; } = 4;

    /// <summary>
    /// The ResourceNode under the cursor within melee reach, or null. Used by the swing to
    /// apply harvest damage. Non-resource surfaces (HittableSurface) drive the tool anim but
    /// leave this null (no damage).
    /// </summary>
    public ResourceNode MeleeResource { get; private set; }

    /// <summary>
    /// The interaction-prompt provider the player is currently targeting (pickup, grapple point,
    /// NPC, …), or null. Generic — the HUD reads this and renders whatever prompt it returns.
    /// </summary>
    public IInteractionPromptProvider HoveredInteractable { get; private set; }

    /// <summary>The GameObject the mouse ray is pointing at (from MousePointer), or null.</summary>
    public GameObject HoveredGameObject
    {
        get
        {
            if (_pointer == null) _pointer = MousePointer.Instance;
            return _pointer != null ? _pointer.HoverObject : null;
        }
    }

    /// <summary>
    /// Unified hover result produced each frame. All consumers should read from this
    /// instead of the individual HoveredXxx properties (which are deprecated).
    /// </summary>
    public PlayerAimHoverResult HoverResult { get; private set; }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Update()
    {
        if (_pointer == null) _pointer = MousePointer.Instance;
        if (_pointer == null) return;

        GameObject hovered = _pointer.HoverObject;
        bool hasHit = _pointer.HasHit;
        Vector3 point = _pointer.WorldPoint;

        UpdateAimPoint(hasHit, point);
        UpdateHoveredResource(hovered);
        UpdateHoveredPickup(hovered);
        UpdateHoveredKeyPickup(hovered);
        UpdateHoveredGrapple(hovered, point);
        UpdateHoveredGrabbable(hovered);
        UpdateMeleeTarget(hovered, hasHit, point);
        UpdateHoveredInteractable(hovered, hasHit, point);

        // Build unified hover result
        BuildHoverResult(hasHit, point, hovered);
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void UpdateAimPoint(bool hasHit, Vector3 point)
    {
        if (hasHit)
        {
            WorldAimPoint = point;
            return;
        }
        // Miss: intersect the horizontal plane at this object's Y so aim still resolves over open ground.
        var plane = new Plane(Vector3.up, new Vector3(0f, transform.position.y, 0f));
        if (plane.Raycast(_pointer.WorldRay, out float dist))
            WorldAimPoint = _pointer.WorldRay.GetPoint(Mathf.Min(dist, _maxAimDistance));
    }

    private void UpdateHoveredResource(GameObject hovered)
    {
        ResourceNode node = Find<ResourceNode>(hovered);
        HoveredResource = node != null && WithinInteractionRange(node.transform.position) ? node : null;
    }

    private void UpdateHoveredPickup(GameObject hovered)
    {
        WorldItemPickup pickup = Find<WorldItemPickup>(hovered);
        HoveredPickup = pickup != null && WithinInteractionRange(pickup.transform.position) ? pickup : null;
    }

    private void UpdateHoveredKeyPickup(GameObject hovered)
    {
        WorldItem item = Find<WorldItem>(hovered);
        // Only key-pickup items (e.g. the wrench) surface here; auto-collect items magnet themselves.
        bool needsKey = item != null && item.Item != null && !item.Item.AutoCollects;
        HoveredKeyPickup = needsKey && WithinInteractionRange(item.transform.position) ? item : null;
    }

    private void UpdateHoveredGrapple(GameObject hovered, Vector3 point)
    {
        // Whichever marker the hovered object carries decides the kind; range is left to the
        // controller (RopeLassoConfig owns it). Anchor and pullable are mutually exclusive.
        RopeAnchor anchor = Find<RopeAnchor>(hovered);
        if (anchor != null)
        {
            HoveredAnchor = anchor;
            HoveredPullable = null;
            HoveredGrapplePoint = point;
            return;
        }

        RopePullable pullable = Find<RopePullable>(hovered);
        HoveredAnchor = null;
        HoveredPullable = pullable;
        if (pullable != null) HoveredGrapplePoint = point;
    }

    private void UpdateMeleeTarget(GameObject hovered, bool hasHit, Vector3 point)
    {
        // ResourceNode wins (it carries damage + its own tool); otherwise a HittableSurface decides
        // the tool; nothing in reach = wrench (air).
        MeleeResource = null;
        SwingAnimIndex = 4;
        if (!hasHit || hovered == null) return;
        if (Vector3.Distance(transform.position, point) > _meleeRange) return;

        ResourceNode node = Find<ResourceNode>(hovered);
        if (node != null)
        {
            MeleeResource = node;
            SwingAnimIndex = node.AttackAnimIndex;
            return;
        }

        HittableSurface surface = Find<HittableSurface>(hovered);
        if (surface != null)
            SwingAnimIndex = surface.AttackAnimIndex;
    }

    private void UpdateHoveredInteractable(GameObject hovered, bool hasHit, Vector3 point)
    {
        HoveredInteractable = null;

        // 1) Generic interaction target within reach — pickups, NPCs, inspectables, etc.
        if (hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange)
        {
            var provider = hovered.GetComponentInParent<IInteractionPromptProvider>();
            if (provider != null) { HoveredInteractable = provider; return; }
        }

        // 2) Fall back to the rope-lasso targets (their reach is owned by the lasso controller,
        //    so they prompt even past the generic interaction range).
        if (HoveredAnchor is IInteractionPromptProvider anchor)        HoveredInteractable = anchor;
        else if (HoveredPullable is IInteractionPromptProvider pull)   HoveredInteractable = pull;
    }

    private void UpdateHoveredGrabbable(GameObject hovered)
    {
        HoveredGrabbable = null;
        if (hovered == null) return;

        Grabbable g = hovered.GetComponentInParent<Grabbable>();
        if (g == null) return;

        // Range gate: must be within interaction range (or already held)
        if (g.IsHeld || Vector3.Distance(transform.position, g.transform.position) <= _interactionRange)
            HoveredGrabbable = g;
    }

    /// <summary>The Grabbable object the mouse ray is pointing at, or null.</summary>
    public Grabbable HoveredGrabbable { get; private set; }

    /// <summary>Component of type T on the hovered object or its parents, or null.</summary>
    private static T Find<T>(GameObject hovered) where T : Component
        => hovered != null ? hovered.GetComponentInParent<T>() : null;

    private bool WithinInteractionRange(Vector3 worldPos)
        => Vector3.Distance(transform.position, worldPos) <= _interactionRange;

    private void BuildHoverResult(bool hasHit, Vector3 point, GameObject hovered)
    {
        HoverResult = new PlayerAimHoverResult
        {
            HasTarget = hasHit || HoveredAnchor != null || HoveredPullable != null || HoveredGrabbable != null,
            WorldPoint = WorldAimPoint,
            WorldItem = HoveredKeyPickup,
            ResourceNode = HoveredResource,
            MeleeResource = MeleeResource,
            RopeAnchor = HoveredAnchor,
            RopePullable = HoveredPullable,
            ScanTarget = hovered != null ? Find<ScanTarget>(hovered) : null,
            Interactable = HoveredInteractable,
            Grabbable = HoveredGrabbable,
            GrapplePoint = HoveredGrapplePoint,
            InInteractionRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange,
            InMeleeRange = hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _meleeRange,
            SwingAnimIndex = SwingAnimIndex,
        };
    }
}

using UnityEngine;

/// <summary>
/// The physical material of a meleeable surface, used to decide which tool the
/// wrench multitool "transforms" into when swung at it (and so which attack
/// animation plays). Air (nothing hovered) is handled by the swing controller,
/// not represented here.
/// </summary>
public enum SurfaceMaterial
{
    Wood,
    Metal,
    Rock,
}

/// <summary>
/// Marks any object as a meleeable surface with a <see cref="SurfaceMaterial"/>.
/// Drop on crates, walls, etc. so the wrench reads them as wood/metal/rock and
/// swings the matching tool. <see cref="ResourceNode"/> does NOT need this — it
/// derives its own tool from its required-tool config; this is for non-resource
/// props that still want the tool-swap read.
///
/// AttackAnimIndex maps SurfaceMaterial → Animator AttackIndex (1-4), matching
/// <see cref="ResourceNode.AttackAnimIndex"/>: Pick = 1 | Axe = 2 | Hammer = 3 | Wrench = 4.
/// </summary>
public class HittableSurface : MonoBehaviour
{
    [Tooltip("Physical material of this surface. Decides which tool the wrench swings: Wood→Axe, Metal→Hammer, Rock→Pick.")]
    [SerializeField] private SurfaceMaterial _material = SurfaceMaterial.Wood;

    public SurfaceMaterial Material => _material;

    /// <summary>Animator AttackIndex for this surface's matching tool.</summary>
    public int AttackAnimIndex => _material switch
    {
        SurfaceMaterial.Wood  => 2, // axe
        SurfaceMaterial.Metal => 3, // hammer
        SurfaceMaterial.Rock  => 1, // pick
        _                     => 4, // wrench (shouldn't hit; defensive)
    };
}

using UnityEngine;
using UnityEngine.Events;
using Flynn.Events;

/// <summary>
/// Marks a world object as a harvestable resource and manages its runtime health.
/// Subscribes to <see cref="ResourceManager.OnResourceHit"/> so it only takes damage
/// when the player's hit targets this object (or a child collider). All static data
/// (required tool, max health, drops) lives in the assigned
/// <see cref="ResourceNodeConfig"/> ScriptableObject.
///
/// Designer-hookable events are exposed as UnityEvents in the Inspector:
///   • <see cref="OnHitEvent"/>      — after each hit that damages this node
///   • <see cref="OnDepletedEvent"/>  — when health reaches zero
///
/// AttackAnimIndex maps RequiredTool → Animator AttackIndex (1-4):
///   Pick = 1 | Axe = 2 | Hammer = 3 | Wrench = 4
/// </summary>
public class ResourceNode : MonoBehaviour
{
    // ── Inspector ─────────────────────────────────────────────────────────────

    [Tooltip("Data asset for this resource type (health, tool, drops). Create via Flynn/Resource/Node Config.")]
    [SerializeField] private ResourceNodeConfig _config;

    [Tooltip("Channel raised on each hit so the HUD can show a world-anchored HP bar. Optional.")]
    [SerializeField] private ResourceHitChannel _hitChannel;

    // ── UnityEvents (designer-hookable) ───────────────────────────────────────

    [Header("Events")]
    [Tooltip("Fired after each hit that damages this node. Argument = remaining health.")]
    [SerializeField] private IntEvent _onHitEvent = new IntEvent();

    [Tooltip("Fired when health reaches zero (before drops / destruction).")]
    [SerializeField] private UnityEvent _onDepletedEvent = new UnityEvent();

    // ── C# events (code-side subscribers) ─────────────────────────────────────

    /// <summary>Raised after each successful hit. Argument is remaining health.</summary>
    public event System.Action<int> OnDamaged;

    /// <summary>Raised when health reaches zero, before drops are spawned.</summary>
    public event System.Action OnDepleted;

    // ── Public properties ─────────────────────────────────────────────────────

    public ResourceNodeConfig Config => _config;

    /// <summary>Current remaining health this session.</summary>
    public int CurrentHealth { get; private set; }

    /// <summary>Maximum health from the config (1 when unconfigured).</summary>
    public int MaxHealth => _config != null ? Mathf.Max(1, _config.maxHealth) : 1;

    /// <summary>Remaining health as a 0-1 fraction.</summary>
    public float Health01 => Mathf.Clamp01((float)CurrentHealth / MaxHealth);

    private bool _depleted;

    /// <summary>Convenience accessor so callers don't have to null-check Config.</summary>
    public ItemType RequiredTool => _config != null ? _config.requiredTool : ItemType.Pick;

    /// <summary>Resource type for effectiveness lookups.</summary>
    public ResourceType ResourceType => _config != null ? _config.resourceType : ResourceType.None;

    /// <summary>Whether this node has been fully depleted this session.</summary>
    public bool IsDepleted => _depleted;

    /// <summary>Display label for hover UI.</summary>
    public string DisplayName => _config != null ? _config.displayName : "Resource";

    /// <summary>
    /// Animator AttackIndex value for this resource's required tool.
    /// Returns 0 when no valid tool is mapped.
    /// </summary>
    public int AttackAnimIndex => RequiredTool switch
    {
        ItemType.Pick   => 1,
        ItemType.Axe    => 2,
        ItemType.Hammer => 3,
        ItemType.Wrench => 4,
        _               => 0,
    };

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        CurrentHealth = _config != null ? _config.maxHealth : 1;
    }

    private void OnEnable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit += HandleResourceManagerHit;
    }

    private void OnDisable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit -= HandleResourceManagerHit;
    }

    // ── Public API ────────────────────────────────────────────────────────────

    /// <summary>
    /// Try to apply a tool hit to this node. Looks up tool effectiveness from the
    /// <see cref="ToolEffectivenessTable"/> on the <see cref="ResourceManager"/>.
    /// If the tool is ineffective (multiplier 0), the hit is rejected and a
    /// <see cref="ResourceHit"/> event is published with zero damage for "wrong tool" feedback.
    /// Returns true if the hit was accepted (even if no damage was dealt).
    /// </summary>
    public bool TryApplyToolHit(ToolHitContext hit)
    {
        if (_depleted) return false;

        float effectiveness = ResourceManager.Instance != null
            ? ResourceManager.Instance.GetEffectiveness(hit.ToolType, ResourceType)
            : 1f;

        int scaledDamage = Mathf.RoundToInt(hit.Damage * effectiveness);

        // Publish hit event regardless (for "wrong tool" feedback)
        PublishEvent(new ResourceHit(this, hit));

        if (scaledDamage <= 0) return false;

        ReceiveHit(scaledDamage);
        return true;
    }

    /// <summary>
    /// Apply <paramref name="damage"/> points to this node. When health reaches
    /// zero the node spawns its drops and destroys itself.
    /// </summary>
    /// <param name="damage">Positive integer damage value.</param>
    public void ReceiveHit(int damage)
    {
        if (CurrentHealth <= 0) return;

        CurrentHealth = Mathf.Max(0, CurrentHealth - damage);

        // C# event (code subscribers)
        OnDamaged?.Invoke(CurrentHealth);

        // UnityEvent (designer-hooked effects)
        _onHitEvent?.Invoke(CurrentHealth);

        // HUD channel
        if (_hitChannel != null) _hitChannel.Raise(this, Health01);

        // GameEventBus (decoupled feedback/audio/UI)
        PublishEvent(new ResourceDamaged(this, damage, CurrentHealth));

        if (CurrentHealth <= 0)
            Deplete();
    }

    // ── Private ───────────────────────────────────────────────────────────────

    /// <summary>
    /// Listener for <see cref="ResourceManager.OnResourceHit"/>. Only applies
    /// damage when the hit targets this object (or a child collider).
    /// </summary>
    private void HandleResourceManagerHit(PlayerHitInfo info)
    {
        if (info.Target == null) return;
        if (!IsThisResource(info.Target)) return;
        ReceiveHit(info.Power);
    }

    /// <summary>True if the target GameObject is this object or a descendant.</summary>
    private bool IsThisResource(GameObject target)
    {
        Transform t = target.transform;
        while (t != null)
        {
            if (t.gameObject == gameObject) return true;
            t = t.parent;
        }
        return false;
    }

    /// <summary>
    /// Node is exhausted. Raises events for the drop-spawner and death-fall
    /// listeners to react (eject drops, topple + fade). The node only destroys
    /// itself here as a fallback when no <see cref="ResourceDeathFall"/> is present
    /// to own the removal.
    /// </summary>
    private void Deplete()
    {
        if (_depleted) return;
        _depleted = true;

        // C# event (code subscribers)
        OnDepleted?.Invoke();

        // UnityEvent (designer-hooked effects)
        _onDepletedEvent?.Invoke();

        // GameEventBus (decoupled feedback/audio/UI)
        PublishEvent(new ResourceDepleted(this));

        if (GetComponent<ResourceDeathFall>() == null)
            Destroy(gameObject);
    }

    // ── Nested types ──────────────────────────────────────────────────────────

    /// <summary>UnityEvent passing remaining health as an int.</summary>
    [System.Serializable]
    public class IntEvent : UnityEvent<int> { }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

