/// <summary>
/// Projectile spawned by WrenchThrowController. Flies outbound to a target point,
/// hovers (returnDelay), then homes back to the thrower like a boomerang and is caught.
/// Spins a child visual for the boomerang look. On impact with a ResourceNode,
/// applies throw damage through the effectiveness system.
/// </summary>
public class ThrownWrench : MonoBehaviour
{
    private enum Phase { Outbound, Hover, Returning }

    private WrenchThrowController _owner;
    private WrenchConfig _config;
    private Vector3 _target;
    private Phase _phase;
    private float _hoverTimer;
    private Transform _spin;
    private Camera _cam;
    private float _roll;
    private bool _hasHitTarget;

    public void Launch(WrenchThrowController owner, Vector3 target, WrenchConfig config)
    {
        _owner   = owner;
        _target  = target;
        _config  = config;
        _phase   = Phase.Outbound;
        _spin    = transform.childCount > 0 ? transform.GetChild(0) : transform;
    }

    private void Update()
    {
        if (_config == null) return;

        switch (_phase)
        {
            case Phase.Outbound:
                MoveToward(_target, _config.throwSpeed);
                if (Reached(_target, 0.1f))
                {
                    _phase = Phase.Hover;
                    _hoverTimer = _config.returnDelay;
                }
                break;

            case Phase.Hover:
                _hoverTimer -= Time.deltaTime;
                if (_hoverTimer <= 0f) _phase = Phase.Returning;
                break;

            case Phase.Returning:
                Vector3 catchPoint = _owner != null ? _owner.CatchPoint : transform.position;
                MoveToward(catchPoint, _config.returnSpeed);
                if (Reached(catchPoint, _config.catchRadius))
                {
                    if (_owner != null) _owner.OnCaught();
                    Destroy(gameObject);
                }
                break;
        }
    }

    /// <summary>
    /// Detect collision with ResourceNodes during the outbound phase.
    /// Uses the effectiveness system to determine damage.
    /// </summary>
    private void OnCollisionEnter(Collision collision)
    {
        if (_phase != Phase.Outbound || _hasHitTarget) return;

        ResourceNode node = collision.gameObject.GetComponentInParent<ResourceNode>();
        if (node == null) return;

        _hasHitTarget = true;

        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;

        int damage = _config != null ? _config.heavySwingDamage : 2;
        Vector3 hitDir = (collision.transform.position - transform.position).normalized;

        var hit = new ToolHitContext(
            source: gameObject,
            toolType: tool,
            action: ToolActionType.Throw,
            damage: damage,
            hitPoint: collision.contacts.Length > 0 ? collision.contacts[0].point : transform.position,
            hitDirection: hitDir,
            charge: 1f
        );

        node.TryApplyToolHit(hit);

        // Immediately start returning after impact
        _phase = Phase.Returning;
    }

    // Billboard the visual to the camera (like the player sprite) and spin it in the
    // screen plane so the boomerang reads as rotating regardless of view angle.
    private void LateUpdate()
    {
        if (_config == null || _spin == null) return;
        if (_cam == null) _cam = Camera.main;
        if (_cam == null) return;

        _roll += _config.spinSpeed * Time.deltaTime;
        _spin.rotation = _cam.transform.rotation * Quaternion.Euler(0f, 0f, _roll);
    }

    private void MoveToward(Vector3 p, float speed)
        => transform.position = Vector3.MoveTowards(transform.position, p, speed * Time.deltaTime);

    private bool Reached(Vector3 p, float radius)
        => (transform.position - p).sqrMagnitude <= radius * radius;
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Manages the hold-to-charge power buildup for swing and throw actions.
/// Controllers call <see cref="BeginCharge"/> on mouse-down and <see cref="ReleaseCharge"/>
/// on mouse-up. The manager drives the charge timer each frame, publishes events for
/// the HUD bar, and returns a <see cref="ChargeResult"/> with scaled damage and battery cost.
///
/// Battery cost and damage scale linearly between light and heavy values in
/// <see cref="PowerBuildupSettings"/>. A "perfect zone" window at the right side
/// of the bar gives a satisfying timing indicator.
/// </summary>
[DefaultExecutionOrder(-35)]
public class PowerBuildupManager : MonoBehaviour
{
    public static PowerBuildupManager Instance { get; private set; }

    [SerializeField] private PowerBuildupSettings _settings;

    private enum State { Idle, Charging }

    private State _state = State.Idle;
    private ActionType _currentType;
    private float _chargeTimer;
    private bool _peaked; // true once charge hits 1.0 (used for decay)

    // ── Public API ──────────────────────────────────────────────────────────

    public bool IsCharging => _state == State.Charging;
    public float ChargeNormalized => _state != State.Charging ? 0f : NormalizedCharge();
    public ActionType CurrentType => _currentType;

    /// <summary>Begin charging for the given action type.</summary>
    public void BeginCharge(ActionType type)
    {
        if (_state == State.Charging) return;

        // Check minimum battery cost
        var battery = RobotBattery.Instance;
        float minCost = type == ActionType.Swing
            ? (_settings != null ? _settings.lightSwingBatteryCost : 2f)
            : (_settings != null ? _settings.lightThrowBatteryCost : 5f);
        if (battery != null && !battery.CanSpend(minCost)) return;

        _state = State.Charging;
        _currentType = type;
        _chargeTimer = 0f;
        _peaked = false;

        Publish(new PowerBuildupStarted(type));
    }

    /// <summary>Release the charge and get the result.</summary>
    public ChargeResult ReleaseCharge()
    {
        if (_state != State.Charging) return default;

        float norm = NormalizedCharge();
        bool isPerfect = _settings != null
            && norm >= _settings.perfectZoneStart
            && norm <= _settings.perfectZoneEnd;

        int damage;
        float batteryCost;
        float animSpeed;

        if (_currentType == ActionType.Swing)
        {
            damage = _settings != null
                ? Mathf.RoundToInt(Mathf.Lerp(_settings.lightSwingDamage, _settings.heavySwingDamage, norm))
                : 1;
            batteryCost = _settings != null
                ? Mathf.Lerp(_settings.lightSwingBatteryCost, _settings.heavySwingBatteryCost, norm)
                : 2f;
            animSpeed = _settings != null
                ? Mathf.Lerp(_settings.lightSwingAnimSpeed, _settings.heavySwingAnimSpeed, norm)
                : 1f;
        }
        else
        {
            damage = _settings != null
                ? Mathf.RoundToInt(Mathf.Lerp(_settings.lightThrowDamage, _settings.heavyThrowDamage, norm))
                : 1;
            batteryCost = _settings != null
                ? Mathf.Lerp(_settings.lightThrowBatteryCost, _settings.heavyThrowBatteryCost, norm)
                : 5f;
            animSpeed = 1f;
        }

        var result = new ChargeResult(norm, isPerfect, damage, batteryCost, animSpeed, _currentType);

        // Spend battery
        var battery = RobotBattery.Instance;
        if (battery != null && batteryCost > 0f) battery.Spend(batteryCost);

        Publish(new PowerBuildupReleased(norm, isPerfect, damage, batteryCost, _currentType));

        _state = State.Idle;
        _chargeTimer = 0f;
        _peaked = false;

        return result;
    }

    /// <summary>Cancel without releasing (e.g. unequipped wrench mid-charge).</summary>
    public void CancelCharge()
    {
        if (_state != State.Charging) return;
        _state = State.Idle;
        _chargeTimer = 0f;
        _peaked = false;
        Publish(new PowerBuildupReleased(0f, false, 0, 0f, _currentType));
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[PowerBuildupManager] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (_state != State.Charging) return;

        float maxTime = _settings != null ? _settings.maxChargeTime : 2f;

        if (!_peaked)
        {
            _chargeTimer += Time.deltaTime;
            if (_chargeTimer >= maxTime)
            {
                _chargeTimer = maxTime;
                _peaked = true;
            }
        }
        else if (_settings != null && _settings.decayRate > 0f)
        {
            _chargeTimer -= _settings.decayRate * Time.deltaTime;
            if (_chargeTimer <= 0f) _chargeTimer = 0f;
        }

        float norm = NormalizedCharge();
        bool inPerfect = _settings != null
            && norm >= _settings.perfectZoneStart
            && norm <= _settings.perfectZoneEnd;

        Publish(new PowerBuildupChanged(norm, inPerfect));
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private float NormalizedCharge()
    {
        float maxTime = _settings != null ? _settings.maxChargeTime : 2f;
        return maxTime > 0f ? Mathf.Clamp01(_chargeTimer / maxTime) : 0f;
    }

    private static void Publish<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

/// <summary>
/// Result of a released charge. Controllers use this to determine damage,
/// battery cost, animation speed, and throw distance scaling.
/// </summary>
public struct ChargeResult
{
    public readonly float Normalized;
    public readonly bool IsPerfect;
    public readonly int Damage;
    public readonly float BatteryCost;
    public readonly float AnimSpeed;
    public readonly ActionType Type;

    public ChargeResult(float normalized, bool isPerfect, int damage, float batteryCost, float animSpeed, ActionType type)
    {
        Normalized = normalized;
        IsPerfect = isPerfect;
        Damage = damage;
        BatteryCost = batteryCost;
        AnimSpeed = animSpeed;
        Type = type;
    }
}

using UnityEngine;

/// <summary>
/// Ejects a <see cref="ResourceNode"/>'s drops when it's depleted, rolling each <see cref="DropEntry"/>
/// in the node's config and spawning the results through <see cref="WorldItemSpawner"/> with a small
/// upward pop so they scatter and settle before flying to the player. Replaces the old inline
/// SpawnDrops on ResourceNode (single responsibility).
/// </summary>
[RequireComponent(typeof(ResourceNode))]
public class ResourceDropSpawner : MonoBehaviour
{
    [Tooltip("Upward impulse applied to each spawned drop so it pops out of the node.")]
    [SerializeField] private float _popImpulse = 1.1f;
    [Tooltip("Height above the node base that drops spawn from.")]
    [SerializeField] private float _spawnHeight = 0.25f;

    private ResourceNode _node;

    private void Awake() => _node = GetComponent<ResourceNode>();

    private void OnEnable()  { _node.OnDepleted += SpawnDrops; }
    private void OnDisable() { if (_node != null) _node.OnDepleted -= SpawnDrops; }

    private void SpawnDrops()
    {
        _node.OnDepleted -= SpawnDrops;

        ResourceNodeConfig cfg = _node.Config;
        if (cfg == null || cfg.drops == null) return;

        foreach (DropEntry drop in cfg.drops)
        {
            if (drop.item == null) continue;
            if (Random.value > drop.dropChance) continue;

            int count = Random.Range(drop.minCount, Mathf.Max(drop.minCount, drop.maxCount) + 1);
            for (int i = 0; i < count; i++)
            {
                Vector2 scatter = Random.insideUnitCircle * cfg.dropScatterRadius;
                Vector3 pos = transform.position + new Vector3(scatter.x, _spawnHeight, scatter.y);
                WorldItemSpawner.Spawn(drop.item, 1, pos, _popImpulse);
            }
        }
    }
}

using System;
